/* assets/i18n/shors-algorithm.js — the 'shor' namespace: title/heading,
   lede, the "How this works" panel (rich: five <strong> children), the
   control labels/chips/buttons, the step-log heading, the Quantum stand-in
   panel, the Rejected bases/cycle/Verdict headings, the ring legend, the
   explainer and ceiling-box panels, the footer, every guard/banner/step/
   attempt/verdict/ring message (built as {key, params} records by
   runShor/parseNStrict/applyGuard and translated at render — never
   concatenated English fragments, T-06-20 pattern), for the Shor's
   Algorithm tool, in all twenty-nine supported languages.

   Classic script, IIFE, "use strict" — its only statement is
   NT.i18n.register(...). Pure math notation (N, a, r, the preset chips'
   "N = 3233"/"N = 3599" numerals, "gcd(...)", "a^(r/2)", "a^1, a^2, a^3,
   ... mod N") is written identically in every language per
   06-GLOSSARY.md section (e) and is built directly in the page script or
   baked into a dictionary value with no further key. Play/Step/Instant/
   Reset/Speed live in the shared `common` namespace (assets/i18n/site.js);
   Randomize base and Factor N are page-specific keys here. Must load
   after assets/nt-i18n.js and assets/i18n/site.js, before the page's own
   inline <script>.
*/
