      lede: 'Het algoritme van Shor is de reden dat RSA sterfelijk wordt genoemd: met een echte kwantumcomputer ontbindt het N in tijd die polynomiaal is in log N. Er is hier geen kwantumcomputer, dus deze pagina vervangt de ene echt kwantummechanische stap door een eerlijke klassieke vervanging en vermeldt dit bij elke stap.',
      introHeading: 'Hoe dit werkt',
      introP1: "Het algoritme van Shor heeft vijf fasen: {0} (haal een even factor eraf, herken een volkomen macht, of herken N meteen als priemgetal), {1} a en bereken de ggd met N, {2} van a mod N — de enige echt kwantummechanische stap, hier uitgevoerd op een klassieke computer — een {3} op die orde, en uiteindelijk {4} dat de orde omzet in twee echte factoren van N.",
