      explainerP1: 'Een echte kwantumcomputer stelt een superpositie op over elke mogelijke exponent x tegelijk, berekent a^x mod N voor allemaal parallel, en past dan een inverse kwantum-Fouriertransformatie (QFT) toe om de verborgen periode van die functie om te zetten in een meetbare piek. Kwantumfase-schatting leest die piek af, en een kettingbreukontwikkeling van de gemeten fase herstelt de exacte orde r — allemaal tegen een kosten die polynomiaal is in log N.',
      explainerP2: 'Deze pagina kan niets daarvan. Ze loopt in plaats daarvan de cyclus a^1, a^2, a^3, … mod N stap voor stap af op een gewone klassieke processor — het enige dat echte kwantumhardware nooit zelf moet doen.',
      ceilingHeading: 'Waarom N stopt bij 4096',
      ceilingP1: 'De klassieke cycluswandeling hierboven kost tot N modulaire vermenigvuldigingen per poging met een grondtal. Een getrouwe simulatie van het kwantumregister dat een echt apparaat zou gebruiken, heeft ongeveer N^2 amplitudes nodig — ruwweg 16.777.216 (16,8 miljoen) bij N = 4096. Beide groeien met N zelf, terwijl een echt algoritme van Shor op echte kwantumhardware alleen groeit met log N. N is hier begrensd op 4096 omdat er geen kwantumcomputer op deze pagina staat — niet omdat de rekenkunde moeilijk is.',
