      introP2: "Order finding is normally the quantum part: real hardware prepares a superposition, evaluates a^x mod N on every exponent x at once, and reads off the period with quantum phase estimation and an inverse quantum Fourier transform (QFT). This page cannot do that, so it walks a^1, a^2, a^3, ... mod N one multiplication at a time instead — exactly the step real Shor's never has to do classically, and the reason N stays small here.",
