      verdictHeading: 'Verdict',
      explainerHeading: 'What the quantum part really does',
      explainerP1: 'A real quantum computer prepares a superposition over every candidate exponent x at once, evaluates a^x mod N on all of them in parallel, and then applies an inverse quantum Fourier transform (QFT) to turn the hidden period of that function into a measurable peak. Quantum phase estimation reads that peak, and a continued fraction expansion of the measured phase recovers the exact order r — all at a cost polynomial in log N.',
      explainerP2: 'This page cannot do any of that. It instead walks the cycle a^1, a^2, a^3, ... mod N one multiplication at a time on an ordinary classical processor — the one thing real quantum hardware never has to do.',
      ceilingHeading: 'Why N stops at 4096',
      ceilingP1: "The classical cycle walk above costs up to N modular multiplications per base attempt. A faithful simulation of the quantum register a real device would use needs about N^2 amplitudes — roughly 16,777,216 (16.8 million) at N = 4096. Both of those grow with N itself, while real Shor's algorithm on real quantum hardware grows only with log N. N is capped here at 4096 because there is no quantum computer on this page — not because the arithmetic is hard.",
      footer: "Shor's algorithm demo — the order-finding step is a classical stand-in for a quantum subroutine. For education only.",
      pillPeriodFinding: 'period finding',
      pillOrderOfA: 'order of a mod N',
      pillQuantumPhaseEstimation: 'quantum phase estimation',
      pillGcdPostProcessing: 'gcd post-processing',
      errNotWhole: 'N must be a whole number with digits only.',
      errTooSmall: 'N must be at least 3 — there is nothing to factor below that.',
      errCeiling: 'N is capped at {max} because this page substitutes a classical cycle walk for the quantum order-finding step: that walk costs up to N modular multiplications per base attempt, and a faithful simulation of the quantum register would need about N^2 amplitudes (roughly 16.8 million at N = {max}). Real Shor’s algorithm runs this step on quantum hardware at a cost polynomial in log N — there is no quantum computer on this page, so larger N is refused.',
      verdictEnterValidN: 'Enter a valid N to run Shor’s algorithm.',
