      strongGcdPostProcessing: 'ggT-Nachbearbeitung',
      introP2: 'Ordnungsbestimmung ist normalerweise der Quantenteil: echte Hardware bereitet eine Superposition vor, berechnet a^x mod N für jeden Exponenten x gleichzeitig und liest die Periode mittels Quantenphasenschätzung und einer inversen Quanten-Fourier-Transformation (QFT) ab. Diese Seite kann das nicht, also läuft sie a^1, a^2, a^3, … mod N stattdessen Schritt für Schritt ab — genau der Schritt, den ein echter Shor-Algorithmus klassisch nie ausführen müsste, und der Grund, warum N hier klein bleibt.',
