      explainerP1: 'Ein echter Quantencomputer bereitet eine Superposition über jeden möglichen Exponenten x gleichzeitig vor, berechnet a^x mod N für alle parallel und wendet dann eine inverse Quanten-Fourier-Transformation (QFT) an, um die verborgene Periode dieser Funktion in einen messbaren Peak zu verwandeln. Quantenphasenschätzung liest diesen Peak ab, und eine Kettenbruchentwicklung der gemessenen Phase gewinnt die exakte Ordnung r zurück — alles mit Kosten, die polynomial in log N sind.',
      explainerP2: 'Diese Seite kann nichts davon. Sie läuft stattdessen den Zyklus a^1, a^2, a^3, … mod N Schritt für Schritt auf einem gewöhnlichen klassischen Prozessor ab — das Einzige, was echte Quantenhardware nie selbst tun muss.',
      ceilingHeading: 'Warum N bei 4096 endet',
      ceilingP1: 'Der klassische Zyklus-Durchlauf oben kostet bis zu N modulare Multiplikationen pro Basisversuch. Eine getreue Simulation des Quantenregisters, das ein echtes Gerät verwenden würde, bräuchte etwa N^2 Amplituden — rund 16.777.216 (16,8 Millionen) bei N = 4096. Beide wachsen mit N selbst, während ein echter Shor-Algorithmus auf echter Quantenhardware nur mit log N wächst. N ist hier auf 4096 begrenzt, weil es auf dieser Seite keinen Quantencomputer gibt — nicht weil die Arithmetik schwierig ist.',
