      standInCaption: "Un ordinateur quantique trouverait cet ordre par estimation de phase quantique et une transformée de Fourier quantique inverse (QFT), en évaluant a^x mod N sur une superposition de chaque exposant x à la fois. Cette page parcourt plutôt le cycle a^1, a^2, a^3, ... mod N classiquement, une multiplication à la fois.",
