      explainerP1: "Un véritable ordinateur quantique prépare une superposition sur chaque exposant candidat x à la fois, évalue a^x mod N sur tous en parallèle, puis applique une transformée de Fourier quantique inverse (QFT) pour transformer la période cachée de cette fonction en un pic mesurable. L'estimation de phase quantique lit ce pic, et un développement en fraction continue de la phase mesurée retrouve l'ordre exact r — tout cela à un coût polynomial en log N.",
      explainerP2: "Cette page ne peut rien faire de tout cela. Elle parcourt plutôt le cycle a^1, a^2, a^3, ... mod N une multiplication à la fois sur un processeur classique ordinaire — la seule chose qu'un véritable matériel quantique n'a jamais à faire.",
      ceilingHeading: 'Pourquoi N s’arrête à 4096',
      ceilingP1: "Le parcours de cycle classique ci-dessus coûte jusqu'à N multiplications modulaires par tentative de base. Une simulation fidèle du registre quantique qu'utiliserait un véritable appareil nécessiterait environ N^2 amplitudes — soit environ 16 777 216 (16,8 millions) pour N = 4096. Les deux croissent avec N lui-même, tandis qu'un véritable algorithme de Shor sur du matériel quantique réel ne croît qu'avec log N. N est limité ici à 4096 car il n'y a pas d'ordinateur quantique sur cette page — pas parce que l'arithmétique est difficile.",
      footer: "Démo de l'algorithme de Shor — l'étape de recherche d'ordre est une solution de remplacement classique pour une sous-routine quantique. À titre éducatif uniquement.",
