      strongFindOrder: 'encontrar el orden',
      strongParityRootCheck: 'comprobación de paridad y raíz',
      strongGcdPostProcessing: 'posprocesamiento por mcd',
      introP2: 'La búsqueda de orden es normalmente la parte cuántica: el hardware real prepara una superposición, evalúa a^x mod N sobre cada exponente x a la vez, y lee el periodo mediante estimación de fase cuántica y una transformada cuántica de Fourier inversa (QFT). Esta página no puede hacer eso, así que recorre a^1, a^2, a^3, ... mod N una multiplicación a la vez — exactamente el paso que un algoritmo de Shor real nunca tiene que hacer clásicamente, y la razón por la que N se mantiene pequeño aquí.',
