      explainerP1: 'Un ordenador cuántico real prepara una superposición sobre cada exponente candidato x a la vez, evalúa a^x mod N sobre todos en paralelo, y luego aplica una transformada cuántica de Fourier inversa (QFT) para convertir el periodo oculto de esa función en un pico medible. La estimación de fase cuántica lee ese pico, y una expansión en fracción continua de la fase medida recupera el orden exacto r — todo ello con un coste polinómico en log N.',
      explainerP2: 'Esta página no puede hacer nada de eso. En cambio, recorre el ciclo a^1, a^2, a^3, ... mod N una multiplicación a la vez en un procesador clásico ordinario — lo único que el hardware cuántico real nunca tiene que hacer.',
      ceilingHeading: 'Por qué N se detiene en 4096',
      ceilingP1: 'El recorrido de ciclo clásico anterior cuesta hasta N multiplicaciones modulares por intento de base. Una simulación fiel del registro cuántico que usaría un dispositivo real necesitaría unas N^2 amplitudes — aproximadamente 16.777.216 (16,8 millones) para N = 4096. Ambas crecen con N mismo, mientras que un algoritmo de Shor real en hardware cuántico real solo crece con log N. N está limitado aquí a 4096 porque no hay ningún ordenador cuántico en esta página — no porque la aritmética sea difícil.',
