      aLabel: 'Forza base a (opzionale)',
      aPlaceholder: 'casuale',
      randomizeBase: 'Base casuale',
      chipRsaModulus: 'N = 3233 (modulo RSA da manuale)',
      chipLongPeriod: 'N = 3599 (periodo lungo)',
      factorN: 'Fattorizza N',
      stepLogHeading: 'Registro dei passi',
      standInHeading: 'Sostituto quantistico',
      standInCaption: 'Un computer quantistico troverebbe questo ordine tramite la stima di fase quantistica e una trasformata di Fourier quantistica inversa (QFT), calcolando a^x mod N su una sovrapposizione di ogni esponente x contemporaneamente. Questa pagina invece percorre il ciclo a^1, a^2, a^3, … mod N classicamente, una moltiplicazione alla volta.',
      rejectedBasesHeading: 'Basi rifiutate',
      cycleHeading: 'Il ciclo di a mod N',
