      verdictHeading: 'Verdetto',
      explainerHeading: 'Cosa fa davvero la parte quantistica',
      explainerP1: 'Un vero computer quantistico prepara una sovrapposizione su ogni esponente candidato x contemporaneamente, calcola a^x mod N su tutti in parallelo, e poi applica una trasformata di Fourier quantistica inversa (QFT) per trasformare il periodo nascosto di quella funzione in un picco misurabile. La stima di fase quantistica legge quel picco, e uno sviluppo in frazione continua della fase misurata recupera l’ordine esatto r — tutto a un costo polinomiale in log N.',
      explainerP2: 'Questa pagina non può fare nulla di tutto ciò. Percorre invece il ciclo a^1, a^2, a^3, … mod N una moltiplicazione alla volta su un normale processore classico — l’unica cosa che il vero hardware quantistico non deve mai fare da solo.',
      ceilingHeading: 'Perché N si ferma a 4096',
      ceilingP1: 'Il percorso di ciclo classico sopra costa fino a N moltiplicazioni modulari per tentativo di base. Una simulazione fedele del registro quantistico che un dispositivo reale userebbe avrebbe bisogno di circa N^2 ampiezze — circa 16.777.216 (16,8 milioni) per N = 4096. Entrambi crescono con N stesso, mentre un vero algoritmo di Shor su hardware quantistico reale cresce solo con log N. N è qui limitato a 4096 perché non c’è nessun computer quantistico su questa pagina — non perché l’aritmetica sia difficile.',
      footer: 'Demo dell’algoritmo di Shor — il passo di ricerca dell’ordine è un sostituto classico per una sottoroutine quantistica. Solo per uso didattico.',
