      errCeiling: 'N jest ograniczone do {max}, bo ta strona zastępuje kwantowy krok wyznaczania rzędu klasycznym przechodzeniem cyklu: to przechodzenie kosztuje do N mnożeń modularnych na próbę z podstawą, a wierna symulacja rejestru kwantowego potrzebowałaby około N^2 amplitud (z grubsza 16,8 miliona przy N = {max}). Prawdziwy algorytm Shora wykonuje ten krok na sprzęcie kwantowym kosztem wielomianowym względem log N — na tej stronie nie ma komputera kwantowego, więc większe N jest odrzucane.',
