      errCeiling: "N é limitado a {max} porque esta página substitui a etapa quântica de encontrar a ordem por um percurso clássico do ciclo: esse percurso custa até N multiplicações modulares por tentativa de base, e uma simulação fiel do registrador quântico precisaria de cerca de N^2 amplitudes (aproximadamente 16,8 milhões em N = {max}). O algoritmo de Shor real executa essa etapa em hardware quântico a um custo polinomial em log N — não há computador quântico nesta página, então um N maior é rejeitado.",
