      bannerFixN: 'Corrija N acima antes de fatorar.',
      stepPrecheckLabel: 'Verificações prévias clássicas',
      stepPrecheckDetail: 'Antes de qualquer busca de ordem: N é par? N é uma potência perfeita? N é primo? Cada um desses casos tem um atalho clássico que não precisa de nenhuma etapa quântica.',
      verdictLabel: 'Veredito',
      detailEven: '{n} é par, então 2 o divide: {n} = {f0} x {f1}.',
      detailPerfectPower: '{n} é uma potência perfeita ({b}^{e}), então {n} = {f0} x {f1}.',
