      stepLogHeading: 'Stegslogg',
      standInHeading: 'Kvantersättning',
      standInCaption: 'En kvantdator skulle hitta den här ordningen via kvantfasestimering och en invers kvant-Fouriertransform (QFT), genom att utvärdera a^x mod N på en superposition av varje exponent x samtidigt. Den här sidan går istället igenom cykeln a^1, a^2, a^3, ... mod N klassiskt, en multiplikation i taget.',
