      verdictHeading: 'Slutsats',
      explainerHeading: 'Vad kvantdelen egentligen gör',
      explainerP1: 'En verklig kvantdator förbereder en superposition över varje kandidatexponent x samtidigt, utvärderar a^x mod N på alla parallellt, och tillämpar sedan en invers kvant-Fouriertransform (QFT) för att omvandla funktionens dolda period till en mätbar topp. Kvantfasestimering läser av den toppen, och en kedjebråksutveckling av den uppmätta fasen återfår den exakta ordningen r — allt till en kostnad som är polynomisk i log N.',
      explainerP2: 'Den här sidan kan inte göra något av det. Den går istället igenom cykeln a^1, a^2, a^3, ... mod N en multiplikation i taget på en vanlig klassisk processor — det enda som riktig kvanthårdvara aldrig behöver göra.',
      ceilingHeading: 'Varför N stoppar vid 4096',
      ceilingP1: 'Den klassiska cykelgenomgången ovan kostar upp till N modulära multiplikationer per basförsök. En trogen simulering av det kvantregister en verklig enhet skulle använda behöver omkring N^2 amplituder — ungefär 16 777 216 (16,8 miljoner) vid N = 4096. Båda dessa växer med N självt, medan riktiga Shors algoritm på riktig kvanthårdvara bara växer med log N. N är begränsat här till 4096 eftersom det inte finns någon kvantdator på den här sidan — inte eftersom aritmetiken är svår.',
      footer: "Demo för Shors algoritm — ordningsbestämningssteget är en klassisk ersättning för en kvantunderrutin. Endast för undervisning.",
