      introHeading: 'Slik fungerer dette',
      introP1: "Shors algoritme har fem trinn: {0} (fjern en jevn faktor, oppdag en perfekt potens, eller gjenkjenn N direkte som primtall), {1} a og ta SFD med N, {2} av a mod N — det ene genuint kvantemekaniske trinnet, her utført på en klassisk datamaskin i stedet — en {3} på den ordenen, og til slutt {4} som gjør ordenen om til to ekte faktorer av N.",
