      introP2: 'מציאת הסדר היא בדרך כלל החלק הקוונטי: חומרה אמיתית מכינה סופרפוזיציה, מעריכה את \u2066a^x mod N\u2069 על כל מעריך x בבת אחת, וקוראת את המחזור באמצעות הערכת פאזה קוונטית וטרנספורם פורייה קוונטי הפוך (QFT). הדף הזה אינו יכול לעשות זאת, ולכן הוא צועד לאורך \u2066a^1, a^2, a^3, ... mod N\u2069 כפל אחר כפל — בדיוק הצעד שהאלגוריתם האמיתי של שור אינו צריך לבצע קלאסית, וזו הסיבה ש-N נשאר כאן קטן.',
