      introP2: 'कोटि ज्ञात करना सामान्यतः क्वांटम हिस्सा है: असली हार्डवेयर अध्यारोपण तैयार करता है, हर घातांक x पर एक साथ a^x mod N का मान निकालता है, और क्वांटम कला आकलन तथा प्रतिलोम क्वांटम फ़ूरिये रूपांतरण (QFT) से आवर्त पढ़ लेता है। यह पृष्ठ ऐसा नहीं कर सकता, इसलिए वह इसके बदले a^1, a^2, a^3, ... mod N को एक-एक गुणा करके चलता है — ठीक वही काम जो असली शोर को क्लासिकल रूप में कभी करना नहीं पड़ता, और यही कारण है कि यहाँ N छोटा रहता है।',
