      explainerP2: 'Kjo faqe nuk mund të bëjë asgjë nga këto. Në vend të kësaj ecën nëpër ciklin a^1, a^2, a^3, ... mod N një shumëzim në herë në një procesor klasik të zakonshëm — gjënë e vetme që hardueri kuantik i vërtetë nuk ka nevojë ta bëjë kurrë.',
      ceilingHeading: 'Pse N ndalon te 4096',
      ceilingP1: 'Ecja klasike nëpër cikël më sipër kushton deri në N shumëzime modulare për çdo provë me bazë. Një simulim besnik i regjistrit kuantik që do të përdorte një pajisje e vërtetë ka nevojë për rreth N^2 amplituda — afërsisht 16,777,216 (16.8 milionë) te N = 4096. Të dyja rriten me vetë N, ndërsa algoritmi i vërtetë i Shorit në harduer kuantik të vërtetë rritet vetëm me log N. N kufizohet këtu në 4096 sepse në këtë faqe nuk ka kompjuter kuantik — jo sepse aritmetika është e vështirë.',
