      explainerP2: '이 페이지는 그 어느 것도 할 수 없습니다. 대신 평범한 고전 프로세서에서 주기 a^1, a^2, a^3, ... mod N을 곱셈 한 번씩 따라갑니다. 이것은 진짜 양자 하드웨어가 결코 하지 않아도 되는 일입니다.',
