      ceilingP1: '위의 고전적 주기 따라가기는 밑 하나를 시도할 때마다 최대 N번의 모듈러 곱셈이 듭니다. 실제 장치가 쓰는 양자 레지스터를 충실하게 시뮬레이션하려면 약 N^2개의 진폭이 필요하며, N = 4096일 때 대략 16,777,216(16.8백만)입니다. 둘 다 N 자체와 함께 늘어나는 반면, 실제 양자 하드웨어에서의 진짜 쇼어 알고리즘은 log N과 함께만 늘어납니다. 여기서 N을 4096으로 제한한 것은 이 페이지에 양자 컴퓨터가 없기 때문이지, 산술이 어려워서가 아닙니다.',
