      explainerP2: 'Tasna ad ur tzmr ad txdm ula yat gsn. Ar tddu ɣf tawrirt a^1, a^2, a^3, ... mod N yan usgut ɣ tikkelt ɣf yan umsiḍn aklasik n yal ass — ayn ur ixṣṣ ardwar aquntum n tidt ad t ixdm ula tikkelt.',
      ceilingHeading: 'Acku tilas n N d 4096',
      ceilingP1: 'Tikli taklasikt n tawrirt afella ar tssɛ lkulfa n N n isgutn imuḍulan ar tilas i yal tɛrrḍt n tasila. Yat asimulasyun aṣṣḥiḥ n umsjjl aquntum ayd ar issmrs ardwar n tidt ar tixṣṣ qrib N^2 n tamblitudin — qrib 16,777,216 (16.8 mlyun) ɣ N = 4096. Sin gsn ar mqqrn s N iman nnes, mac alguritm n Cur n tidt ɣf ardwar aquntum n tidt ar yqqr kigan s log N. Tilas n N dagi d 4096 acku ur illi amsiḍn aquntum ɣ tasna ad — ur d acku asiḍn ɛzzn.',
