      introP1: 'Algorîtma Shor pênc qonaxên wê hene: {0} (faktora cot rake, hêzeke temam nas bike, an jî hejmareke seretayî rasterast nas bike), {1} a û girtina gcd-ya wê bi N re, {2} ya a mod N — yekane gava rastî kuantûmî, ku li vir li şûna wê li ser komputerekî klasîk tê kirin — {3} li ser wê rêzê, û di dawiyê de {4} ku rêzê dike du faktorên rastîn ên N.',
      strongPrechecks: 'pêşkontrolên klasîk',
      strongPickBase: 'hilbijartina bingehê',
      strongFindOrder: 'dîtina rêzê',
      strongParityRootCheck: 'kontrola cotî û kokê',
      strongGcdPostProcessing: 'pêvajoya paşê ya gcd',
      introP2: 'Dîtina rêzê bi gelemperî beşa kuantûmî ye: alavên rastîn serhevdanînekê amade dikin, a^x mod N li ser her hêza x bi carekê hesab dikin, û dewrê bi texmînkirina qonaxa kuantûmî û veguherîna Fourier a kuantûmî ya berevajî (QFT) dixwînin. Ev rûpel nikare vê bike, ji ber vê li şûna wê a^1, a^2, a^3, ... mod N lêkdan bi lêkdan dimeşe — tam ew gav ku Shor ya rastîn tu carî nahewce ye wî bi klasîk bike, û sedema ku N li vir biçûk dimîne.',
