      explainerP1: 'Komputerekî kuantûmî yê rastîn serhevdanînekê li ser her hêza namzed x bi carekê amade dike, a^x mod N li ser hemûyan bi paralelî hesab dike, paşê veguherîna Fourier a kuantûmî ya berevajî (QFT) bi kar tîne da ku dewra veşartî ya wê fonksiyonê bike lûtkeyekî ku dikare were pîvandin. Texmînkirina qonaxa kuantûmî wê lûtkeyê dixwîne, û berfirehbûna kesra berdewam a qonaxa pîvayî rêza r a rast vedigerîne — hemû bi lêçûneke polînomî di log N de.',
      explainerP2: 'Ev rûpel nikare tu tiştekî ji van bike. Li şûna wê dewra a^1, a^2, a^3, ... mod N lêkdan bi lêkdan li ser pêvajoyek klasîk a asayî dimeşe — yekane tiştê ku alavên kuantûmî yên rastîn tu carî nahewce ye bikin.',
      ceilingHeading: 'Çima N li 4096 disekine',
      ceilingP1: 'Dewra klasîk a meşê ya li jor heta N lêkdanên modulî bi her hewldana bingehê lê dike. Simulasyoneke dilsoz a qeydeya kuantûmî ya ku cîhazeke rastîn bi kar bîne bi qasî N^2 amplîtûdan hewce dike — nêzîkî 16,777,216 (16.8 milyon) li N = 4096. Her du bi N bixwe mezin dibin, lê Shor ya rastîn li ser alavên kuantûmî yên rastîn tenê bi log N mezin dibe. N li vir li 4096 hatiye sînorkirin ji ber ku li ser vê rûpelê komputerekî kuantûmî tune — ne ji ber ku hesab dijwar e.',
