      explainerP1: 'کۆمپیوتەرێکی کوانتەمی ڕاستەقینە سوپەرپۆزیشنێک لەسەر ھەموو تواناکانی پالێوراوی x بە یەکجار ئامادە دەکات، \u2066a^x mod N\u2069 لەسەر ھەمووی بە ھاوتەریبی دەژمێرێت، ئینجا گۆڕینی فووریێی کوانتەمی پێچەوانە (QFT) بەکار دەھێنێت بۆ ئەوەی خولی شاراوەی ئەو فەنکشنە بکات بە لووتکەیەکی پێوانەکراو. خەمڵاندنی قۆناغی کوانتەمی ئەو لووتکەیە دەخوێنێتەوە، و فراوانکردنی کەرتی بەردەوامی قۆناغی پێوراو پلەی ڕاستی r دەگەڕێنێتەوە — ھەموو بە تێچوویەکی پۆلینۆمی لە \u2066log N\u2069.',
      explainerP2: 'ئەم پەڕەیە ناتوانێت ھیچ شتێک لەمانە بکات. لەبری ئەوە خولی \u2066a^1, a^2, a^3, ... mod N\u2069 لێکدان بە لێکدان لەسەر پڕۆسێسەرێکی کلاسیکی ئاسایی دەڕوات — تاکە شتێک کە ئامێری کوانتەمی ڕاستەقینە ھەرگیز پێویستی بەوە نییە بیکات.',
      ceilingHeading: 'بۆچی N لە 4096 دەوەستێت',
      ceilingP1: 'خولی کلاسیکی ڕۆیشتن لە سەرەوە تا N لێکدانی مۆدیولی بۆ ھەر تاقیکردنەوەیەکی بنچینە دەخایەنێت. ھاوشێوەکردنێکی دڵسۆزانەی تۆمارە کوانتەمییەکە کە ئامێرێکی ڕاستەقینە بەکاری دەھێنێت پێویستی بە نزیکەی \u2066N^2\u2069 ئەمپلیتیود ھەیە — نزیکەی 16,777,216 (16.8 ملیۆن) لە \u2066N = 4096\u2069. ھەردووکیان لەگەڵ خودی N گەورە دەبن، لە کاتێکدا شۆری ڕاستەقینە لەسەر ئامێری کوانتەمی ڕاستەقینە تەنیا لەگەڵ \u2066log N\u2069 گەورە دەبێت. N لێرە لە 4096 سنووردار کراوە چونکە لەسەر ئەم پەڕەیە کۆمپیوتەری کوانتەمی نییە — نەک چونکە ژماردنەکە قورسە.',
